parameters.jsCode:
const execution = $input.first().json.execution || {};
const workflow = $input.first().json.workflow || {};
const errorObj = execution.error || {};

const executionId = execution.id || 'unknown-exec-id';
const workflowName = workflow.name || 'Self-Healing SRE Incident Commander';
const workflowId = workflow.id || 'incident-commander';
const errorMessage = errorObj.message || 'Unknown internal execution error in AI SRE pipeline';
const errorStack = errorObj.stack || 'No stack trace provided';
const timestamp = new Date().toISOString();
const n8nBaseUrl = ($env.N8N_EDITOR_BASE_URL || 'http://localhost:5678').replace(/\/+$/, '');
const executionUrl = `${n8nBaseUrl}/workflow/${workflowId}/executions/${executionId}`;

return [{
  json: {
    execution_id: executionId,
    workflow_name: workflowName,
    workflow_id: workflowId,
    error_message: errorMessage,
    error_stack: errorStack,
    timestamp: timestamp,
    execution_url: executionUrl
  }
}];

